import React, { useEffect, useState } from "react";
import Papa from "papaparse";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from "recharts";
import { Box, Container, Grid, Typography, Select, MenuItem, FormControl, InputLabel } from "@mui/material";
import HomeHeaderNavi from './components/Nav/homepageheader';
import { useNavigate, Link } from 'react-router-dom';
import Footer from "./components/Footer/footer";
type DataRow = {
  title: string;
  [key: string]: any;  // 他のカラムのデータ
};



const LineChartFromCSV: React.FC = () => {
  const [data, setData] = useState<DataRow[]>([]);
  const [datathisweek, setDataThisWeek] = useState<DataRow[]>([]);
  const [displayPeriod, setDisplayPeriod] = useState<number>(4); // 表示期間（週数）
  const [filteredData, setFilteredData] = useState<DataRow[]>([]);
  const [currentDate, setCurrentDate] = useState<string>('2025-09-22'); // 最新の日付

  // 各作品の表示状態を管理
  const [visibleSeries, setVisibleSeries] = useState<{ [key: string]: boolean }>({
    "『ONE PIECE』尾田栄一郎": true,
    "僕とロボコ": true,
    "SAKAMOTO DAYS": true,
    "逃げ上手の若君": true,
    "ウィッチウォッチ": true,
    "アオのハコ": true,
    "あかね噺": true,
  });

  useEffect(() => {
    fetch("/data.csv")
      .then((response) => response.text())
      .then((csvText) => {
        const parsed = Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          dynamicTyping: true,
        });
        const parsedData = parsed.data as DataRow[];
        // 最新日付のインデックスを見つける
        const currentDateIndex = parsedData.findIndex(item => item.title === '2025-09-22');
        if (currentDateIndex !== -1) {
          const startIndex = Math.max(currentDateIndex - displayPeriod + 1, 0);
          setFilteredData(parsedData.slice(startIndex, currentDateIndex + 1));
        }
        setData(parsedData);
      });
    fetch("/data2.csv")
      .then((response) => response.text())
      .then((csvText) => {
        const parsed = Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          dynamicTyping: true,
        });
        setDataThisWeek(parsed.data as DataRow[]);
      });
  }, []);

  // 表示期間が変更されたときのフィルタリング
  useEffect(() => {
    if (data.length > 0) {
      setFilteredData(data.slice(-displayPeriod));
    }
  }, [displayPeriod, data]);

  // テーブルのカラム名を取得（データが空の場合は空配列）
  const columns = datathisweek.length > 0 ? Object.keys(datathisweek[0]) : [];

  return (
    <>
      <HomeHeaderNavi/>
      <Typography variant="h5" component="div" gutterBottom
        sx={{marginTop: 5, marginBottom:3,textAlign: 'center',fontWeight:"bold"}}
      >
        2025年 43号(今週号)の作品順位
      </Typography>
      {/* テーブル表示 */}
      <table border={1} cellPadding={4} cellSpacing={0} style={{ marginBottom: 32 }} className="styled-table">
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {datathisweek.map((row, idx) => (
            <tr key={idx}>
              {columns.map((col, colIndex) => (
                <td key={col}>
                  {colIndex === 0 ? (
                    <Link 
                      to={`/detail?title=${encodeURIComponent(String(row[col as keyof DataRow]))}`}
                      style={{ 
                        color: '#0066cc', 
                        textDecoration: 'none'
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.textDecoration = 'underline';
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.textDecoration = 'none';
                      }}
                    >
                      {row[col as keyof DataRow]}
                    </Link>
                  ) : (
                    row[col as keyof DataRow]
                  )}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
       {/* スタイル定義 */}
      <style>{`
        .styled-table {
          border-collapse: collapse;
          margin: 20px 0;
          font-size: 16px;
          min-width: 400px;
          box-shadow: 0 0 10px rgba(0,0,0,0.08);
          width: 100%;
        }
        .styled-table thead tr {
          background-color: #009879;
          color: #ffffff;
          text-align: left;
        }
        .styled-table th, .styled-table td {
          padding: 12px 15px;
          border: 1px solid #dddddd;
        }
        .styled-table tbody tr {
          border-bottom: 1px solid #dddddd;
          background-color: #f3f3f3;
        }
        .styled-table tbody tr:nth-of-type(even) {
          background-color: #e9f7f6;
        }
        .styled-table tbody tr:hover {
          background-color: #b7eadc;
        }
      `}</style>

      {/* グラフ表示 */}
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 10, marginBottom: 3 }}>
        <Typography variant="h5" component="div" sx={{fontWeight:"bold"}}>
          掲載順位の推移
        </Typography>
        <FormControl sx={{ minWidth: 120 }}>
          <InputLabel>表示期間</InputLabel>
          <Select
            value={displayPeriod}
            label="表示期間"
            onChange={(e) => setDisplayPeriod(Number(e.target.value))}
          >
            <MenuItem value={4}>1ヶ月</MenuItem>
            <MenuItem value={12}>3ヶ月</MenuItem>
            <MenuItem value={24}>6ヶ月</MenuItem>
            <MenuItem value={48}>1年</MenuItem>
            <MenuItem value={1000}>全期間</MenuItem>
          </Select>
        </FormControl>
      </Box>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={filteredData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis 
            dataKey="title" 
            reversed={true}
            tick={{ fontSize: 12 }}
          />
          <YAxis 
            reversed={true}
            domain={[1, 'dataMax']}
            tickCount={10}
          />
          <Tooltip />
          <Legend onClick={(e: any) => {
            if (e.dataKey) {
              setVisibleSeries(prev => ({
                ...prev,
                [e.dataKey as string]: !prev[e.dataKey as string]
              }));
            }
          }} />
          <Line 
            type="monotone" 
            dataKey="『ONE PIECE』尾田栄一郎" 
            stroke="#8884d8" 
            strokeOpacity={visibleSeries["『ONE PIECE』尾田栄一郎"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="僕とロボコ" 
            stroke="#d8681d" 
            strokeOpacity={visibleSeries["僕とロボコ"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="SAKAMOTO DAYS" 
            stroke="#82ca9d" 
            strokeOpacity={visibleSeries["SAKAMOTO DAYS"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="逃げ上手の若君" 
            stroke="#0fc7f0" 
            strokeOpacity={visibleSeries["逃げ上手の若君"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="ウィッチウォッチ" 
            stroke="#6206e3" 
            strokeOpacity={visibleSeries["ウィッチウォッチ"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="アオのハコ" 
            stroke="#d213bf" 
            strokeOpacity={visibleSeries["アオのハコ"] ? 1 : 0.2}
          />
          <Line 
            type="monotone" 
            dataKey="あかね噺" 
            stroke="#55ff00ff" 
            strokeOpacity={visibleSeries["あかね噺"] ? 1 : 0.2}
          />
        </LineChart>
      </ResponsiveContainer>
      <Footer />
    </>
  );
};

export default LineChartFromCSV;
